'use strict';
function shoppingRequirementNote(s){const r=s.purchase?.requirement;if(!r)return '';return '<p class="tiny muted">'+esc(r.state==='active'?'Generated requirement · '+r.needed+' missing from available stock':r.state==='satisfied'?'Requirement satisfied · orders and receipts retained':r.state==='removed'?'Removed from the plan · orders and receipts retained':r.state==='completed'?'Plan completed · orders and receipts retained':'Plan cancelled · orders and receipts retained')+'</p>';}
function shoppingConflicts(rows=[]){return rows.length?'<details class="note info"><summary>Shared stock needs attention · '+rows.length+' part(s)</summary><p>Plans do not reserve stock. These plans compete for the same available pieces. Shortages are calculated per plan; check the combined need before ordering.</p>'+rows.map(r=>'<p><strong>'+esc(r.name)+'</strong> · '+r.required+' planned / '+r.available+' available<br><span class="tiny">'+esc(r.plans.join(' · '))+'</span></p>').join('')+'</details>':'';}
const shoppingFilters={listId:'',status:'outstanding',query:'',maker:'',supplier:'',source:'',groupBySupplier:false};
const shoppingItem=s=>s.purchase?.item.kind==='free'?s.purchase.item:s.purchase?.item.kind==='supply'?db.supplies.find(p=>p.id===s.purchase.item.id)||{name:'Unavailable supply'}:db.parts.find(p=>p.id===s.partId)||{name:'Unavailable part'};
const shoppingLists=()=>db.planning.shoppingLists||[{id:'general',name:'General shopping',source:{kind:'general'}}];
function shoppingSelect(name,label,options,value='',blank='All'){
 return `<label class="field">${esc(label)}<select name="${esc(name)}">${blank!==null?`<option value="">${esc(blank)}</option>`:''}${options.map(([id,title])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(title)}</option>`).join('')}</select></label>`;
}
function shoppingRows(lines){return lines.map(s=>{
 const p=shoppingItem(s),kind=s.purchase?.item.kind||'part',job=db.jobs.find(j=>j.id===s.jobId),car=job&&db.cars.find(c=>c.id===job.carId),list=shoppingLists().find(l=>l.id===s.purchase?.listId),ordered=s.purchase?.ordered||0;
 return `<article class="purchase-card"><label class="check-row"><input type="checkbox" data-purchase-select="${esc(s.id)}" ${shoppingSelected.has(s.id)?'checked':''}>Select purchase</label><div class="purchase-heading">${kind==='free'?uiTile('box','amber'):itemVisual(p)}<div><h3>${esc(p.name)}</h3><p class="tiny muted">${esc([kind==='free'?'Free-text item':kind==='supply'?'Workshop supply':'Catalogue part',p.maker,p.reference].filter(Boolean).join(' · '))}</p></div>${badge(s.quantity===0?'History':s.received===s.quantity?'Received':ordered?'Ordered':'To buy',s.received===s.quantity?'good':'')}</div><div class="purchase-counts"><span><strong>${s.quantity-s.received-ordered}</strong> to buy</span><span><strong>${ordered}</strong> ordered</span><span><strong>${s.received} / ${s.quantity}</strong> received</span></div><p class="tiny muted">${esc([list?.name,s.supplier||'No supplier',s.date?'Expected '+date(s.date):''].filter(Boolean).join(' · '))}</p>${purchasePriceNote(s)}${shoppingRequirementNote(s)}${job&&job.status!=='active'&&!s.purchase?.requirement?`<p class="tiny muted">Job ${esc(job.status)} · manually added purchase retained.</p>`:''}${s.notes?`<p class="prewrap">${esc(s.notes)}</p>`:''}${s.url?`<p class="tiny muted purchase-url">Purchase link: ${esc(s.url)}</p>`:''}<div class="purchase-source">${job?btn('Open job · '+esc([car?.name,job.name].filter(Boolean).join(' · ')),'open-job','small',job.id):''}${s.buildId?`<span class="tiny muted">Build: ${esc(s.buildName||'Saved build')}</span>${s.buildCarId?btn('View built car','open-car','small',s.buildCarId):s.buildAvailable?btn('Open build','build-load-draft','small',s.buildId):''}`:''}</div><footer class="actions">${btn('Edit','shop-edit','small',s.id)}${purchaseOrderButtons(s)}${s.received<s.quantity?btn(kind==='free'?'Choose stock record…':'Receive…','shop-receive','small',s.id):''}${!s.received&&!ordered&&!purchaseHasHistory(s)&&s.purchase?.requirement?.state!=='active'?btn('Remove','shop-remove','small ghost',s.id):''}</footer></article>`;
 }).join('');}
function renderShoppingPage(){
 if(!local())return empty('Shopping List','Select your local collection to manage purchases.');
 const info=db._view?.shopping||{makers:[],suppliers:[],counts:{}},lists=shoppingLists(),active=lists.find(l=>l.id===shoppingFilters.listId);
 const filters=shoppingSelect('maker','Manufacturer',info.makers.map(x=>[x,x]),shoppingFilters.maker,'All manufacturers')+shoppingSelect('supplier','Supplier',info.suppliers.map(x=>[x,x]),shoppingFilters.supplier,'All suppliers')+shoppingSelect('source','Source',[['general','General purchases'],['build','Build from Scratch'],['job','Workshop / rebuild']],shoppingFilters.source,'All sources');
 return heading('Shopping List','Plan purchases for your collection, builds and workshop.',btn('Update requirements','shop-reconcile')+btn(icon('plus')+' Add shopping item','shop-add','primary'))+`<div class="purchasing-layout"><aside class="purchasing-lists"><h2>Your lists</h2>${btn('All purchases','shop-list',shoppingFilters.listId?'':'active')}${lists.map(l=>btn(esc(l.name),'shop-list',shoppingFilters.listId===l.id?'active':'',l.id)).join('')}${btn(icon('plus')+' New list','shop-new-list','small')}${active?.source.kind==='manual'?btn('Rename list','shop-rename-list','small',active.id):''}</aside><section class="purchasing-main"><div class="tabs purchasing-status">${[['outstanding','Outstanding'],['toBuy','To buy'],['ordered','Ordered'],['received','Received / history']].map(([id,name])=>btn(name+' '+badge(info.counts[id]||0),'shop-status',shoppingFilters.status===id?'active':'',id)).join('')}</div><form id="shopping-filters"><label class="field">Find a purchase<input name="query" value="${esc(shoppingFilters.query)}" placeholder="Name, reference, supplier or notes" maxlength="500"></label><div class="purchase-filters">${filters}</div><div class="actions"><button class="btn" type="submit">Apply filters</button>${btn('Clear filters','shop-reset','ghost')}</div></form><p class="plan-help">Adding an item plans a purchase. Receiving adds stock; it does not fit parts to a car. Supply quantities count items or containers. Update requirements recalculates saved builds and linked setup jobs; manually added purchases stay as entered.</p>${shoppingConflicts(info.conflicts)}${purchaseToolbar(info)}${db.planning.shopping.length?purchaseGroupedRows(db.planning.shopping):empty('No purchases in this view','Add an item or choose another list or filter.')}${viewPager(db._view?.list)}</section></div>`;
}
function addShopping(partId='',jobId='',quantity=1){
 const requested=db.parts.find(p=>p.id===partId);if(requested&&purchaseStockIssue(requested,true)){const original=db.parts.find(p=>p.id===requested.sourcePartId&&!purchaseStockIssue(p,true));if(original)partId=original.id;else{toast(purchaseStockIssue(requested,true),true);return;}}
 const parts=db.parts.filter(p=>!purchaseStockIssue(p,true)),supplies=db.supplies.filter(s=>!s.archived),revision=db.revision;
 const kind=partId||parts.length?'part':'free';
 modal('Add to shopping list',`<div class="form-grid">${shoppingSelect('kind','Item type',[['part','Catalogue part'],['supply','Workshop supply'],['free','Free-text item']],kind,null)}<div class="wide" data-purchase-kind="part">${shoppingSelect('partId','Catalogue part',parts.map(p=>[p.id,[p.name,p.maker,p.reference].filter(Boolean).join(' · ')]),partId||parts[0]?.id,'Choose a part')}</div><div class="wide" data-purchase-kind="supply">${shoppingSelect('supplyId','Workshop supply',supplies.map(p=>[p.id,[p.name,p.maker,p.reference].filter(Boolean).join(' · ')]),'','Choose a supply')}</div><div class="wide form-grid" data-purchase-kind="free">${field('name','Item name')}${field('maker','Manufacturer (optional)')}${field('reference','Reference (optional)')}</div>${field('quantity','Quantity needed',quantity,'number')}${shoppingSelect('jobId','For workshop job',db.jobs.filter(j=>j.status==='active').map(j=>[j.id,[db.cars.find(c=>c.id===j.carId)?.name,j.name].filter(Boolean).join(' · ')]),jobId,'No linked job')}${shoppingSelect('listId','Shopping list',shoppingLists().map(l=>[l.id,l.name]),page==='Shopping List'?shoppingFilters.listId:'','Automatic: job list or General shopping')}${field('supplier','Supplier')}${purchasePriceFields()}${field('date','Expected date','','date')}${field('url','Purchase link (optional)')}${field('notes','Notes','','textarea')}</div><p class="plan-help">Free-text items need no catalogue record. Choose a stock record before receiving them; no stock is created by adding a purchase.</p>`,async v=>{
  const item=v.kind==='free'?{kind:'free',name:v.name.trim(),maker:v.maker.trim(),reference:v.reference.trim()}:{kind:v.kind,id:v.kind==='supply'?v.supplyId:v.partId};
  await change('planning.shopping.add',{revision,item,quantity:v.quantity,jobId:v.jobId,listId:v.listId,supplier:v.supplier,date:v.date,url:v.url,notes:v.notes,unitPrice:v.unitPrice,currency:v.currency});await refreshJob();
 },'Add shopping item');
 const input=$('#dialog [name=quantity]');input.min='1';input.max='1000000';input.step='1';input.required=true;purchaseKindFields();
}
function purchaseKindFields(){const kind=$('#dialog [name=kind]')?.value;if(!kind)return;for(const el of document.querySelectorAll('[data-purchase-kind]')){el.hidden=el.dataset.purchaseKind!==kind;for(const input of el.querySelectorAll('input,select'))input.disabled=el.hidden;}for(const [key,type]of [['partId','part'],['supplyId','supply'],['name','free']]){const el=$('#dialog [name='+key+']');if(el)el.required=kind===type;}}
function editShopping(id){const s=db.planning.shopping.find(s=>s.id===id);if(!s)throw Error('Shopping item not found.');const revision=db.revision,item=s.purchase?.item;
 modal('Edit purchase · '+shoppingItem(s).name,`<div class="form-grid">${item?.kind==='free'?field('name','Item name',item.name)+field('maker','Manufacturer',item.maker)+field('reference','Reference',item.reference):''}${!s.buildId&&!s.purchase?.requirement?field('quantity','Total quantity needed',s.quantity,'number'):''}${shoppingSelect('listId','Shopping list',shoppingLists().map(l=>[l.id,l.name]),s.purchase?.listId||'general',null)}${field('supplier','Supplier',s.supplier)}${purchasePriceFields(s)}${field('date','Expected date',s.date,'date')}${field('url','Purchase link',s.url||'')}${field('notes','Notes',s.notes,'textarea')}</div><p class="plan-help">Moving lists preserves the linked build or workshop job.${s.buildId||s.purchase?.requirement?' Required quantities follow the linked build or setup job.':''}</p>`,async v=>{if(item?.kind==='free'){v.item={kind:'free',name:v.name.trim(),maker:v.maker.trim(),reference:v.reference.trim()};delete v.name;delete v.maker;delete v.reference;}await change('planning.shopping.edit',{revision,id,...v});await refreshJob();},'Save purchase');
 const input=$('#dialog [name=quantity]');if(input){input.min=String(Math.max(1,s.received+(s.purchase?.ordered||0)));input.max='1000000';input.step='1';input.required=true;}
}
function linkShopping(id){const s=db.planning.shopping.find(s=>s.id===id),revision=db.revision;if(!s)throw Error('Shopping item not found.');
 const options=[...db.parts.filter(p=>!purchaseStockIssue(p,true)).map(p=>['part:'+p.id,'Part · '+p.name+' · '+(p.reference||'')]),...db.supplies.filter(p=>!p.archived).map(p=>['supply:'+p.id,'Supply · '+p.name+' · '+(p.reference||'')])];
 modal('Choose stock record · '+shoppingItem(s).name,shoppingSelect('target','Receive future deliveries into',options,'','Choose a stock record')+'<p>This links the purchase to the record you choose. It does not receive any stock yet. Its original description is retained.</p><p class="muted">If the record does not exist, add it in Parts or Workshop supplies with zero owned quantity, then return here.</p>',async v=>{const [kind,key]=v.target.split(':');await change('planning.shopping.edit',{revision,id,item:{kind,id:key}});await refreshJob();},'Link stock record');$('#dialog [name=target]').required=true;
}
async function shoppingAction(action,id){
 if(await shoppingOrderAction(action,id))return true;
 if(action==='shop-reconcile'){await change('planning.shopping.reconcile',{revision:db.revision});await refreshJob();render();toast('Build and workshop requirements updated. Orders and receipts kept.');return true;}
 if(action==='shop-list'){shoppingFilters.listId=id||'';render();return true;}
 if(action==='shop-status'){shoppingFilters.status=id;render();return true;}
 if(action==='shop-reset'){Object.assign(shoppingFilters,{query:'',maker:'',supplier:'',source:''});render();return true;}
 if(action==='shop-new-list'||action==='shop-rename-list'){const list=shoppingLists().find(l=>l.id===id),revision=db.revision;modal(list?'Rename shopping list':'New shopping list',field('name','List name',list?.name||''),async v=>{const key=await change('planning.list.save',{revision,...(list?{id}:{}),name:v.name});shoppingFilters.listId=key;},'Save list');$('#dialog [name=name]').required=true;return true;}
 if(action==='shop-edit'){editShopping(id);return true;}
 if(action==='shop-link'){linkShopping(id);return true;}
 if(action==='shop-receive'){
  const s=db.planning.shopping.find(s=>s.id===id);if(s?.purchase?.item.kind==='free'){linkShopping(id);return true;}
  if(s?.purchase?.item.kind==='supply'){const p=shoppingItem(s),revision=db.revision;modal('Receive · '+p.name,field('quantity','Items / containers received',s.quantity-s.received,'number')+'<p>Only the number of owned items changes. Remaining consumable amounts stay as recorded.</p><label class="check-row"><input type="checkbox" name="confirmed" required>I have received these physical supplies.</label>',async v=>{await change('planning.receive',{revision,shoppingId:id,quantity:v.quantity,confirmed:!!v.confirmed});await refreshJob();},'Add to my stock');const q=$('#dialog [name=quantity]');q.min='1';q.max=String(s.quantity-s.received);q.step='1';q.required=true;return true;}
 }
 return false;
}
document.addEventListener('change',e=>{if(e.target.matches('#dialog [name=kind]'))purchaseKindFields();});
document.addEventListener('submit',e=>{if(e.target.id!=='shopping-filters')return;e.preventDefault();const values=new FormData(e.target);for(const key of ['query','maker','supplier','source'])shoppingFilters[key]=String(values.get(key)||'').trim();render();});
